let items = [];
let revs = {};
const listEl = document.getElementById('list');
const msgEl = document.getElementById('msg');
const nameEl = document.getElementById('newname');

function say(t) { msgEl.textContent = t; }

async function load() {
  const res = await tessera.call('data.read', {});
  items = Array.isArray(res.data.items) ? res.data.items : [];
  revs = (res.revisions && res.revisions.items) || {};
  render();
}

function render() {
  listEl.textContent = '';
  for (const it of items) {
    const li = document.createElement('li');
    li.setAttribute('data-hook', 'item');
    if (it.done) li.classList.add('done');
    const lab = document.createElement('label');
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.checked = !!it.done;
    const nm = document.createElement('span');
    nm.className = 'nm';
    nm.textContent = it.name;
    lab.appendChild(cb);
    lab.appendChild(nm);
    const rm = document.createElement('button');
    rm.type = 'button';
    rm.className = 'rm';
    rm.setAttribute('data-hook', 'item-remove');
    rm.textContent = 'Remove';
    rm.setAttribute('aria-label', 'Remove ' + it.name);
    cb.addEventListener('change', () => toggle(it.id, cb.checked));
    rm.addEventListener('click', () => removeOne(it.id));
    li.appendChild(lab);
    li.appendChild(rm);
    listEl.appendChild(li);
  }
  const total = items.length;
  const got = items.filter((i) => i.done).length;
  document.getElementById('count').textContent = total ? got + ' of ' + total + ' ticked' : '';
  document.getElementById('empty').hidden = total !== 0;
  document.getElementById('clear').hidden = got === 0;
}

async function run(ops, fail) {
  try {
    await tessera.call('data.patch', { operations: ops });
    say('');
    await load();
    return true;
  } catch (e) {
    say(fail);
    await load().catch(() => {});
    return false;
  }
}

async function toggle(id, done) {
  const rc = revs[id];
  await run([{ op: 'replace', collection: 'items', id: id, revisionCount: rc, fields: { done: done } }], 'Could not update that item. Please try again.');
}

async function removeOne(id) {
  const rc = revs[id];
  await run([{ op: 'remove', collection: 'items', id: id, revisionCount: rc }], 'Could not remove that item. Please try again.');
}

async function addItem() {
  const name = nameEl.value.trim();
  if (!name) {
    say('Type the name of an item first.');
    nameEl.focus();
    return;
  }
  const ok = await run([{ op: 'add', collection: 'items', record: { name: name, done: false } }], 'Could not add that item. Your text is still there; please try again.');
  if (ok) nameEl.value = '';
  nameEl.focus();
}

document.getElementById('addbtn').addEventListener('click', addItem);
nameEl.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); addItem(); }
});
document.getElementById('clear').addEventListener('click', async () => {
  const ops = [];
  for (const it of items) {
    if (it.done) ops.push({ op: 'remove', collection: 'items', id: it.id, revisionCount: revs[it.id] });
  }
  if (ops.length) await run(ops, 'Could not remove the ticked items. Please try again.');
});

load().catch(() => say('Could not load the list.'));

