let items = [];
let revs = {};
const listEl = document.getElementById('list');
const msgEl = document.getElementById('msg');
const nameEl = document.getElementById('newname');
const aisleEl = document.getElementById('newaisle');
const NONE = 'No aisle';

function say(t) { msgEl.textContent = t; }

async function load() {
  const res = await tessera.call('data.read', {});
  items = Array.isArray(res.data.items) ? res.data.items : [];
  revs = (res.revisions && res.revisions.items) || {};
  render();
}

function buildItem(it) {
  const li = document.createElement('li');
  li.setAttribute('data-hook', 'item');
  if (it.done) li.classList.add('done');
  const lab = document.createElement('label');
  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.checked = !!it.done;
  const nm = document.createElement('span');
  nm.className = 'nm';
  nm.textContent = it.name;
  lab.appendChild(cb);
  lab.appendChild(nm);
  const rm = document.createElement('button');
  rm.type = 'button';
  rm.className = 'rm';
  rm.setAttribute('data-hook', 'item-remove');
  rm.textContent = 'Remove';
  rm.setAttribute('aria-label', 'Remove ' + it.name);
  cb.addEventListener('change', () => toggle(it.id, cb.checked));
  rm.addEventListener('click', () => removeOne(it.id));
  li.appendChild(lab);
  li.appendChild(rm);
  return li;
}

function render() {
  listEl.textContent = '';
  const groups = new Map();
  for (const it of items) {
    const a = typeof it.aisle === 'string' ? it.aisle.trim() : '';
    const key = a || NONE;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(it);
  }
  const names = Array.from(groups.keys()).filter((k) => k !== NONE).sort((a, b) => a.localeCompare(b));
  if (groups.has(NONE)) names.push(NONE);
  for (const g of names) {
    const sec = document.createElement('section');
    const h = document.createElement('h2');
    h.textContent = g;
    const ul = document.createElement('ul');
    ul.className = 'list';
    for (const it of groups.get(g)) ul.appendChild(buildItem(it));
    sec.appendChild(h);
    sec.appendChild(ul);
    listEl.appendChild(sec);
  }
  const dl = document.getElementById('aisles');
  dl.textContent = '';
  for (const g of names) {
    if (g === NONE) continue;
    const o = document.createElement('option');
    o.value = g;
    dl.appendChild(o);
  }
  const total = items.length;
  const got = items.filter((i) => i.done).length;
  document.getElementById('count').textContent = total ? got + ' of ' + total + ' ticked' : '';
  document.getElementById('empty').hidden = total !== 0;
  document.getElementById('clear').hidden = got === 0;
}

async function run(ops, fail) {
