  const name = nameEl.value.trim();
  const aisle = aisleEl.value.trim();
  if (!name) {
    say('Type the name of an item first.');
    nameEl.focus();
    return;
  }
  const ok = await run([{ op: 'add', collection: 'items', record: { name: name, done: false, aisle: aisle } }], 'Could not add that item. Your text is still there; please try again.');
  if (ok) nameEl.value = '';
  nameEl.focus();
}

